//! Literal compatibility vectors for public KMS opcodes 9-14.

pub(super) fn hex<const N: usize>(value: &str) -> [u8; N] {
    let digits = value.as_bytes();
    assert_eq!(digits.len(), N * 2, "golden vector length mismatch");
    let mut output = [0u8; N];
    let mut index = 0;
    while index < N {
        let high = (digits[index * 2] as char).to_digit(16).expect("hex digit") as u8;
        let low = (digits[index * 2 + 1] as char)
            .to_digit(16)
            .expect("hex digit") as u8;
        output[index] = (high << 4) | low;
        index += 1;
    }
    output
}

